import { lazy } from 'react';
import { BookMarked as IcBookMarked, Code2 as IcCode2, Database as IcDatabase, FileSignature as IcFileSignature, Plug as IcPlug, Settings2 as IcSettings2 } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Platform & Integrations — hub page for the Settings menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 6 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'PlatformCenter'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const SystemSettings = lazy(() => import('./SystemSettings'));
const IntegrationsHub = lazy(() => import('./IntegrationsHub'));
const TallyIntegration = lazy(() => import('./TallyIntegration'));
const ZohoSignIntegration = lazy(() => import('./ZohoSignIntegration'));
const APIDocumentation = lazy(() => import('./APIDocumentation'));
const DatabaseTest = lazy(() => import('./DatabaseTest'));

export const TABS = [
  { id: 'system', label: 'System Settings', icon: IcSettings2, page: 'SystemSettings', Component: SystemSettings },
  { id: 'integrations', label: 'Integrations', icon: IcPlug, page: 'IntegrationsHub', Component: IntegrationsHub },
  { id: 'tally', label: 'Tally', icon: IcBookMarked, page: 'TallyIntegration', Component: TallyIntegration },
  { id: 'zoho', label: 'Zoho Sign', icon: IcFileSignature, page: 'ZohoSignIntegration', Component: ZohoSignIntegration },
  { id: 'api', label: 'API Documentation', icon: IcCode2, page: 'APIDocumentation', Component: APIDocumentation },
  { id: 'db', label: 'Database Test', icon: IcDatabase, page: 'DatabaseTest', Component: DatabaseTest },
];

export default function PlatformCenter({ setPage }) {
  return (
    <TabHub
      icon={IcPlug}
      eyebrow="Settings"
      title="Platform & Integrations"
      subtitle="System settings, connected systems, the API reference and database tooling"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
